    if (logs == null) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if (log.equals("../")) {
            if (depth > 0) {
                depth--;
            }
        } else if (log.equals("./")) {
            // no change
        } else {
            // any other operation is considered moving into a subfolder
            depth++;
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n < 0) throw new IllegalArgumentException("n must be non-negative");
    if (k < n || k > 26 * n) throw new IllegalArgumentException("k must be between n and 26*n inclusive");
    char[] result = new char[n];
    for (int i = 0; i < n; i++) result[i] = 'a';
    int remaining = k - n; // amount of value to distribute beyond the initial 'a's
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // max increase for a character
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

